<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { Check, RefreshCw, ShieldAlert, X } from 'lucide-vue-next'; import { fetchModerationTasks, moderateTask } from '../api/client'; import type { ModerationTask } from '../api/types'; import StatusPanel from '../components/StatusPanel.vue'
const tasks = ref<ModerationTask[]>([]); const loading = ref(false); const error = ref(''); const reasons = ref<Record<number, string>>({})
async function load() { loading.value = true; error.value = ''; try { tasks.value = await fetchModerationTasks() } catch (reason) { error.value = reason instanceof Error ? reason.message : '审核队列暂时不可用' } finally { loading.value = false } }
async function act(task: ModerationTask, action: 'approve' | 'reject' | 'require-changes') { const reason = reasons.value[task.taskId]?.trim(); if (!reason) { error.value = '每个审核操作都必须填写理由'; return } try { await moderateTask(task.taskId, action, reason); tasks.value = tasks.value.filter(item => item.taskId !== task.taskId) } catch (failure) { error.value = failure instanceof Error ? failure.message : '审核操作失败' } }
onMounted(load)
</script>
<template><div class="page-stack admin-page"><section class="page-intro"><span class="eyebrow">OPERATIONS / 独立后台</span><h1>内容审核台</h1><p>普通用户导航不会暴露这个入口；每次决策都必须留下理由和审计记录。</p></section><div class="admin-toolbar"><span>{{ tasks.length }} 个待处理任务</span><button class="button button-quiet" type="button" @click="load"><RefreshCw :size="15" /> 刷新</button></div><StatusPanel v-if="error && !tasks.length" title="审核队列暂时不可用" :detail="error" action-label="重试" @retry="load" /><p v-else-if="error" class="form-error" role="alert">{{ error }}</p><div v-if="loading" class="loading-line">正在读取审核任务…</div><section v-else class="moderation-list"><article v-for="task in tasks" :key="task.taskId" class="moderation-card"><header><div><span class="risk-pill" :class="`risk-${task.riskLevel.toLowerCase()}`">{{ task.riskLevel }}</span><h2>{{ task.title }}</h2><p>任务 #{{ task.taskId }} · 内容 #{{ task.postId }} · {{ task.queue }}</p></div><strong>{{ task.riskScore }}</strong></header><div class="moderation-reason"><ShieldAlert :size="17" /><span><strong>机器提示</strong>{{ task.reason }}</span></div><label :for="`reason-${task.taskId}`">审核理由</label><textarea :id="`reason-${task.taskId}`" v-model="reasons[task.taskId]" rows="3" placeholder="说明通过、驳回或要求修改的具体原因"></textarea><footer><button class="button button-quiet" type="button" @click="act(task, 'require-changes')">要求修改</button><button class="button button-danger" type="button" @click="act(task, 'reject')"><X :size="15" /> 驳回</button><button class="button button-primary" type="button" @click="act(task, 'approve')"><Check :size="15" /> 通过</button></footer></article><section v-if="!tasks.length" class="empty-panel"><Check :size="22" /><h2>审核队列已清空</h2><p>新的投稿会在这里出现。</p></section></section></div></template>
